private final ConcurrentHashMap<String, SynchronousQueue<Reply>> pending = new ConcurrentHashMap<>();

public Reply call(String body) throws InterruptedException {
    var id = UUID.randomUUID().toString();
    var handoff = new SynchronousQueue<Reply>();
    pending.put(id, handoff);                                  // register before send
    try {
        transport.send(new Request(id, body));
        return handoff.poll(5, TimeUnit.SECONDS);              // virtual thread parks cheaply
    } finally { pending.remove(id); }
}
